#include <vector>
#include <algorithm>
#include <cmath>

class Solution {
public:
    int findTheDistanceValue(std::vector<int>& arr1, std::vector<int>& arr2, int d) {
        std::sort(arr2.begin(), arr2.end());
        int count = 0;
        for (int x : arr1) {
            auto it = std::lower_bound(arr2.begin(), arr2.end(), x);
            bool valid = true;
            if (it != arr2.end() && std::abs(*it - x) <= d) valid = false;
            if (it != arr2.begin() && std::abs(*(it - 1) - x) <= d) valid = false;
            if (valid) count++;
        }
        return count;
    }
};

import java.util.*;

class Solution {
    public int findTheDistanceValue(int[] arr1, int[] arr2, int d) {
        Arrays.sort(arr2);
        int count = 0;
        for (int x : arr1) {
            int idx = Arrays.binarySearch(arr2, x);
            if (idx >= 0) continue;
            int insert = -idx - 1;
            boolean valid = true;
            if (insert < arr2.length && Math.abs(arr2[insert] - x) <= d) valid = false;
            if (insert > 0 && Math.abs(arr2[insert - 1] - x) <= d) valid = false;
            if (valid) count++;
        }
        return count;
    }
}

var findTheDistanceValue = function(arr1, arr2, d) {
    arr2.sort((a, b) => a - b);
    let count = 0;
    for (const x of arr1) {
        let left = 0, right = arr2.length - 1, found = false;
        while (left <= right) {
            const mid = (left + right) >> 1;
            if (Math.abs(arr2[mid] - x) <= d) {
                found = true;
                break;
            }
            if (arr2[mid] < x) left = mid + 1;
            else right = mid - 1;
        }
        if (!found) count++;
    }
    return count;
};
